package co.fallsoft.pocket

import org.json.JSONObject

/** Provider item IDs can be regenerated by history reconstruction. A verified
 * client send ID identifies one user input within its turn, never its text.
 * Environment/thread isolation is owned by PocketTranscript's snapshot scope.
 */
internal fun transcriptMessageIdentity(kind:String,turn:String,client:String,provider:String):String =
    if(kind=="user" && turn.isNotBlank() && client.isNotBlank()) "$turn/client-user/$client" else provider

internal fun normalizeTranscriptMessage(row:JSONObject):JSONObject {
    val original=row.s("id")
    val identity=transcriptMessageIdentity(row.s("kind"),row.s("turnId"),row.s("clientId"),original)
    if(identity==original)return row
    return JSONObject(row.toString()).put("id",identity).put("providerRowId",row.s("providerRowId").ifBlank{original})
}

/** Preserve the earliest display slot; newer evidence supplies current metadata.
 * This also repairs caches written before semantic message identity existed.
 */
internal fun normalizeTranscriptMessages(rows:List<JSONObject>,preferIncoming:Boolean=false):List<JSONObject> {
    // Identity evidence may arrive later than the provider item itself. Join
    // only an exact same-turn provider reference with one unambiguous send ID.
    // Text, timestamps and adjacency are never identity evidence.
    val claims=mutableMapOf<Pair<String,String>,MutableSet<String>>()
    fun references(row:JSONObject)=listOf(row.s("id"),row.s("providerRowId"),
        row.s("itemId").takeIf{it.isNotBlank()}?.let{row.s("turnId")+"/"+it}.orEmpty())+
        row.optJSONArray("providerRowIds")?.let{a->(0 until a.length()).map{a.optString(it)}}.orEmpty()
    rows.filter{it.s("kind")=="user"&&it.s("turnId").isNotBlank()&&it.s("clientId").isNotBlank()}.forEach{row->
        references(row).filter{it.isNotBlank()}.forEach{ref->claims.getOrPut(row.s("turnId") to ref){mutableSetOf()}.add(row.s("clientId"))}
    }
    val values=linkedMapOf<String,JSONObject>()
    rows.forEach{original->
        val candidates=if(original.s("kind")=="user"&&original.s("clientId").isBlank())
            references(original).flatMap{claims[original.s("turnId") to it].orEmpty()}.toSet() else emptySet()
        val raw=if(candidates.size==1)JSONObject(original.toString()).put("clientId",candidates.single())else original
        val row=normalizeTranscriptMessage(raw);val id=row.s("id");val old=values[id]
        val chosen=if(old==null||preferIncoming||row.optLong("version")>=old.optLong("version"))row else old
        // Oldest evidence first; a new provider reference must survive the bound.
        val aliases=listOfNotNull(old,row).flatMap{v->
            v.optJSONArray("providerRowIds")?.let{a->(0 until a.length()).map{a.optString(it)}}.orEmpty()+v.s("providerRowId")
        }.filter{it.isNotBlank()}.asReversed().distinct().asReversed().takeLast(32)
        values[id]=if(aliases.isEmpty())chosen else JSONObject(chosen.toString()).put("providerRowIds",org.json.JSONArray(aliases))}
    return values.values.toList()
}
internal fun transcriptDisplayAnchor(rows:List<JSONObject>,provider:String?):String? =
    provider?.let{anchor->rows.firstOrNull{it.s("id")==anchor||it.s("providerRowId")==anchor||it.optJSONArray("providerRowIds")?.let{a->(0 until a.length()).any{n->a.optString(n)==anchor}}==true||"${it.s("turnId")}/${it.s("itemId")}"==anchor}?.s("id")?:anchor}

/** Resolve only persisted anchors while the full legacy rows still exist.
 * Bounded display alias retention must not discard a saved reading/gap anchor.
 * Unknown or conflicting aliases remain unchanged rather than guessing a row.
 */
internal fun migrateTranscriptAnchors(original:List<JSONObject>,requested:Set<String>):Map<String,String> {
    // One linear pass resolves references from all retained interval windows.
    if(requested.isEmpty())return emptyMap()
    val matches=mutableMapOf<String,String>()
    val ambiguous=mutableSetOf<String>()
    original.forEach{row->
        val identity=transcriptMessageIdentity(row.s("kind"),row.s("turnId"),row.s("clientId"),row.s("id"))
        fun observe(alias:String){
            if(alias.isBlank()||alias !in requested)return
            val previous=matches.putIfAbsent(alias,identity)
            if(previous!=null&&previous!=identity)ambiguous.add(alias)
        }
        observe(row.s("id"));observe(row.s("providerRowId"))
        if(row.s("turnId").isNotBlank()&&row.s("itemId").isNotBlank())observe("${row.s("turnId")}/${row.s("itemId")}")
        row.optJSONArray("providerRowIds")?.let{aliases->for(n in 0 until aliases.length())observe(aliases.optString(n))}
    }
    return requested.associateWith{if(it in ambiguous)it else matches[it]?:it}
}

internal fun transcriptProviderItem(row:JSONObject):String = row.s("itemId").ifBlank{
    row.s("providerRowId").ifBlank{row.s("id")}.removePrefix(row.s("turnId")+"/")
}
internal data class TranscriptInputEvent(val row:JSONObject?,val newInput:Boolean,val needsPosition:Boolean)
/** One ingress identity for display, novelty and canonical position lookup.
 * A newer provider reference is new ordering evidence, not another user send.
 */
internal fun transcriptInputEvent(previous:List<JSONObject>,raw:JSONObject?):TranscriptInputEvent {
    val row=raw?.let{normalizeTranscriptMessage(it)}
    if(row==null||row.s("kind")!="user")return TranscriptInputEvent(row,false,false)
    val old=previous.firstOrNull{it.s("id")==row.s("id")}
    val fresh=old==null
    val admitted=old==null||row.optLong("version")>=old.optLong("version")
    val changed=old!=null&&transcriptProviderItem(old)!=transcriptProviderItem(row)
    return TranscriptInputEvent(row,fresh,admitted&&(fresh||changed))
}

/** Metadata replacement must retain bounded provider evidence for the same send. */
internal fun mergeTranscriptMessageEvidence(previous:JSONObject?,incoming:JSONObject,preferIncoming:Boolean=false):JSONObject {
    if(previous==null||previous.s("id")!=incoming.s("id")||incoming.s("kind")!="user"||incoming.s("clientId").isBlank())return incoming
    return normalizeTranscriptMessages(listOf(previous,incoming),preferIncoming).single()
}

/** Reconcile snapshot identity enrichment in linear time before page ordering.
 * The caller supplies only its current environment/thread's rows. */
internal fun promoteTranscriptIdentityEvidence(rows:List<JSONObject>,evidence:List<JSONObject>):List<JSONObject>{
    val claims=mutableMapOf<Pair<String,String>,MutableSet<String>>()
    evidence.filter{it.s("kind")=="user"&&it.s("clientId").isNotBlank()&&it.s("turnId").isNotBlank()}.forEach{row->
        val refs=listOf(row.s("id"),row.s("providerRowId"))+
            row.optJSONArray("providerRowIds")?.let{a->(0 until a.length()).map{a.optString(it)}}.orEmpty()
        refs.filter{it.isNotBlank()}.forEach{ref->claims.getOrPut(row.s("turnId") to ref){mutableSetOf()}.add(row.s("clientId"))}
    }
    return normalizeTranscriptMessages(rows.map{row->
        val ids=claims[row.s("turnId") to row.s("id")].orEmpty()
        if(row.s("kind")=="user"&&row.s("clientId").isBlank()&&ids.size==1)
            normalizeTranscriptMessage(JSONObject(row.toString()).put("clientId",ids.single()))else row
    })
}

/** Delivery controls remain available after a transport timeout, but a proven
 * provider echo owns the single visible body for that send. Never compare text. */
internal fun transcriptContainsReply(rows:List<JSONObject>,replyId:String):Boolean =
    replyId.isNotBlank()&&rows.any{it.s("kind")=="user"&&it.s("clientId")==replyId}

internal fun resolveTranscriptReadPosition(rows:List<JSONObject>,position:TranscriptReadPosition?):TranscriptReadPosition? =
    position?.let{if(rows.any{row->row.s("id")==it.rowId})it else it.copy(rowId=migrateTranscriptAnchors(rows,setOf(it.rowId))[it.rowId]?:it.rowId)}

/** Late restoration retains older local content while current live/read values
 * own shared identities and ordering. Explicit source authority avoids comparing
 * counters from different runtimes. Disk also normalizes old versions at ingress;
 * this contract must hold independently. Cache metadata never dispatches work. */
internal fun mergeRestoredTranscriptRows(cached:List<JSONObject>,current:List<JSONObject>):List<JSONObject>{
    val evidence=normalizeTranscriptMessages(cached+current)
    val old=promoteTranscriptIdentityEvidence(cached,evidence)
    val previous=old.associateBy{it.s("id")}
    val fresh=promoteTranscriptIdentityEvidence(current,evidence).map{mergeTranscriptMessageEvidence(previous[it.s("id")],it,preferIncoming=true)}
    return groupTranscriptTurns(mergeTranscriptPage(old,fresh,false,{it.s("id")},{it.optLong("version")},keepPosition={it.s("kind")=="turn"},preferIncoming=true))
}


/** A canonical turn is one contiguous block even when its last row arrives
 * after a newer turn. Association comes only from provider turn IDs. This does
 * not guess the order of inputs/output inside a turn, or sort by arrival time.
 * First-seen block order is retained; page ordering owns shared row order. */
internal fun groupTranscriptTurns(rows:List<JSONObject>):List<JSONObject>{
    var previous:String?=null
    val seen=hashSetOf<String>()
    var split=false
    for(row in rows){
        val turn=row.s("turnId").ifBlank{"unscoped:"+row.s("id")}
        if(turn!=previous){if(!seen.add(turn))split=true;previous=turn}
    }
    if(!split)return rows
    val groups=linkedMapOf<String,MutableList<JSONObject>>()
    for(row in rows){
        val turn=row.s("turnId").ifBlank{"unscoped:"+row.s("id")}
        groups.getOrPut(turn){mutableListOf()}.add(row)
    }
    return groups.values.flatten()
}
